package com.prasannjeet.klokka.mail;

import io.quarkus.qute.TemplateData;
import java.util.List;

// Everything templates/digest.html shows, already translated and formatted (CHQ-148, CHQ-189). The template is
// generated by scripts/emails/build.mjs from the same layout as the Logto emails; it only places these values.
@TemplateData
public record DigestMail(String lang, String subject, String title1, String title2, String greeting, String intro,
        List<Workspace> workspaces, String action, String webUrl, String unsubscribe, String footer, String site,
        String siteHost, String teamTitle, String jobsTitle, String totalLabel) {

    // `team` is the employer's table (empty for an employee), `people` the job lists (a null name for an employee's
    // own), `fileLine` names the attached workbook (null when the workspace had nothing), `moreLine` says how many
    // jobs only the workbook lists (null unless the email's job cap was reached).
    @TemplateData
    public record Workspace(String emoji, String name, String range, List<Day> days, String hoursLabel, String hours,
            String monthLabel, String monthHours, List<TeamRow> team, List<PersonJobs> people, String fileLine,
            String moreLine) {}

    // One cell of the week grid: `hot` is the week's busiest day, `off` a day without hours.
    @TemplateData
    public record Day(String label, String value, boolean hot, boolean off) {}

    // One person in the employer's "Team this week" table: Monday to Sunday, then the week.
    @TemplateData
    public record TeamRow(String name, List<TeamCell> days, String total) {}

    // `zero` cells show a muted dash.
    @TemplateData
    public record TeamCell(String value, boolean zero) {}

    @TemplateData
    public record PersonJobs(String name, String total, List<DayJobs> days) {}

    @TemplateData
    public record DayJobs(String label, List<JobLine> jobs) {}

    // "09:00", "Café Nord", "4 h"; time is empty for a job without a start.
    @TemplateData
    public record JobLine(String time, String place, String hours) {}
}
